
IF  NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'GENHSEGMENT') AND type in (N'U'))
BEGIN
CREATE TABLE [dbo].[GENHSEGMENT](
	[FLDID] [varchar](10) NOT NULL,
	[SEGMENT] [varchar](10) NOT NULL,
	[FLDCOM] [bit] NULL,
	[FLDCOMA] [bit] NULL,
 CONSTRAINT [I_GENHSEGMENT] PRIMARY KEY CLUSTERED 
(
	[FLDID] ASC,	
	[SEGMENT] ASC
)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
) ON [PRIMARY]

ALTER TABLE [dbo].[GENHSEGMENT]  WITH NOCHECK ADD  CONSTRAINT [FK_GENHSEGMENT_GENHTAB] FOREIGN KEY([FLDID])
REFERENCES [dbo].[GENHTAB] ([FLDID])
ON UPDATE CASCADE
ON DELETE CASCADE

ALTER TABLE [dbo].[GENHSEGMENT] CHECK CONSTRAINT [FK_GENHSEGMENT_GENHTAB]
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Field ID (see GenHTab)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'GENHSEGMENT', @level2type=N'COLUMN',@level2name=N'FLDID'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Segment Code (see Segment)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'GENHSEGMENT', @level2type=N'COLUMN',@level2name=N'SEGMENT'
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Field Compulsory Entry Flag (0 : No, 1 : Yes)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'GENHSEGMENT', @level2type=N'COLUMN',@level2name=N'FLDCOM'
end
GO


DROP FUNCTION FN_GENDTAB
GO
CREATE FUNCTION FN_GENDTAB (@P_FLDID as varchar(10), @P_TOC as varchar(10),@P_SEGMENT as varchar(10), @P_ISTYPE as varchar(1))     
RETURNS Table
AS RETURN (

Select G1.FLDID, G1.VALUEID, G1.DESCRIPTION, G1.AllowedF, 
G1.FLDCHGINF,
G1.FLDID1,
G1.VALUEID1,
G1.VALUEDESC1,
G1.FLDID2,
G1.VALUEID2,
G1.VALUEDESC2,
G1.FLDID3,
G1.VALUEID3,
G1.VALUEDESC3,
G1.FLDID4,
G1.VALUEID4,
G1.VALUEDESC4,
G1.FLDID5,
G1.VALUEID5,
G1.VALUEDESC5,
G1.FLDID6,
G1.VALUEID6,
G1.VALUEDESC6,
G1.FLDID7,
G1.VALUEID7,
G1.VALUEDESC7,
G1.FLDID8,
G1.VALUEID8,
G1.VALUEDESC8,
G1.FLDID9,
G1.VALUEID9,
G1.VALUEDESC9,
G1.FLDID10,
G1.VALUEID10,
G1.VALUEDESC10,
G1.FLDID11,
G1.VALUEID11,
G1.VALUEDESC11,
G1.FLDID12,
G1.VALUEID12,
G1.VALUEDESC12,
G1.FLDID13,
G1.VALUEID13,
G1.VALUEDESC13,
G1.FLDID14,
G1.VALUEID14,
G1.VALUEDESC14,
G1.FLDID15,
G1.VALUEID15,
G1.VALUEDESC15,
Case When G1.VALUEID=(Select top 1 AccSearch.ValueID from AccSearch Where AccSearch.FLDID=@P_FLDID Order by AccSearch.ANO) Then 1 else 0 end as RecentUsed    
from GenDTab G1 
Inner Join GenHTab G2 on (G2.FLDID=G1.FLDID)    
Outer Apply (Select Top 1 ValueID from GenDTOC G3 Where G2.SubClassF=1 and @P_TOC<>'' and G3.FLDID=G1.FLDID and G3.VALUEID=G1.VALUEID and (G3.TOC='<All>' or G3.TOC=@P_TOC)) G3
Outer Apply (Select Top 1 ValueID from GenDSegment G3 Where G2.SegmentF=1 and @P_SEGMENT<>'' and G3.FLDID=G1.FLDID and G3.VALUEID=G1.VALUEID and (G3.SEGMENT='<All>' or G3.SEGMENT=@P_SEGMENT)) G4
Outer Apply (Select Top 1 ValueID from GenDISTYPE G3 Where G2.ISTYPEF=1 and @P_ISTYPE<>'' and G3.FLDID=G1.FLDID and G3.VALUEID=G1.VALUEID and (G3.ISTYPE='<All>' or G3.ISTYPE=@P_ISTYPE)) G5
Where G1.FLDID=@P_FLDID
and (G2.SubClassF=0 or @P_TOC='' or coalesce(G3.ValueID,'')<>'')
and (G2.SegmentF=0 or @P_SEGMENT='' or coalesce(G4.ValueID,'')<>'')
and (G2.ISTYPEF=0 or @P_ISTYPE='' or coalesce(G5.ValueID,'')<>'')       
)

GO

IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'FN_GENHTAB') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) )
BEGIN
DROP FUNCTION FN_GENHTAB
END
GO
CREATE FUNCTION FN_GENHTAB (@P_FLDID as varchar(10), @P_SEGMENT as varchar(10))     
RETURNS Table
AS RETURN (

Select 
G1.FLDTAB, 
Case when G1.FLDCOM=1 Then G1.FLDCOM Else coalesce(G2.FLDCOM, cast(0 as Bit)) End as FLDCOM,
Case when G1.FLDCOMA=1 Then G1.FLDCOMA Else coalesce(G2.FLDCOMA, cast(0 as Bit)) End as FLDCOMA,
G1.FLDDFORMAT,
G1.FLDIFORMAT,
G1.FLDTYPE,
G1.SUBLINKF, 
G1.FLDSEARCH,
G1.FLDCRITERIA,
G1.FLDCHGINF,
G1.FLDLOWER,
G1.FLDUPPER,
G1.FLDREGEX,
G1.FLDFUNC,
G1.FLDMAP,
G1.FLDID1
from GenHTab G1
Outer Apply (Select Top 1 G2.FLDCOM, G2.FLDCOMA from GenHSegment G2 Where G2.FLDID=G1.FLDID and (G2.SEGMENT='<All>' or G2.SEGMENT=@P_SEGMENT)) G2
Where G1.FLDID=@P_FLDID
)

GO

