TOC.FLDID2, TOC.FLDTAG2, TOC.FLDTAGA2, GENHTAB_2.FLDTAB AS FLDTAB2, GENHTAB_2.FLDCOM AS FLDCOM2, GENHTAB_2.FLDCOMA AS FLDCOMA2, GENHTAB_2.FLDDFORMAT AS FLDDFORMAT2, GENHTAB_2.FLDIFORMAT AS FLDIFORMAT2, GENHTAB_2.FLDTYPE AS FLDTYPE2, GENHTAB_2.SUBLINKF AS SUBLINKF2,  GENHTAB_2.FLDSEARCH AS FLDSEARCH2, GENHTAB_2.FLDCRITERIA AS FLDCRITERIA2, GENHTAB_2.FLDCHGINF as FLDCHGINF2, GENHTAB_2.FLDLOWER as FLDLOWER2, GENHTAB_2.FLDUPPER as FLDUPPER2, GENHTAB_2.FLDREGEX as FLDREGEX2, GENHTAB_2.FLDFUNC as FLDFUNC2, GENHTAB_2.FLDMAP as FLDMAP2, CASE WHEN GENHTAB_2.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF2,
TOC.FLDID3, TOC.FLDTAG3, TOC.FLDTAGA3, GENHTAB_3.FLDTAB AS FLDTAB3, GENHTAB_3.FLDCOM AS FLDCOM3, GENHTAB_3.FLDCOMA AS FLDCOMA3, GENHTAB_3.FLDDFORMAT AS FLDDFORMAT3, GENHTAB_3.FLDIFORMAT AS FLDIFORMAT3, GENHTAB_3.FLDTYPE AS FLDTYPE3, GENHTAB_3.SUBLINKF AS SUBLINKF3,  GENHTAB_3.FLDSEARCH AS FLDSEARCH3, GENHTAB_3.FLDCRITERIA AS FLDCRITERIA3, GENHTAB_3.FLDCHGINF as FLDCHGINF3, GENHTAB_3.FLDLOWER as FLDLOWER3, GENHTAB_3.FLDUPPER as FLDUPPER3, GENHTAB_3.FLDREGEX as FLDREGEX3, GENHTAB_3.FLDFUNC as FLDFUNC3, GENHTAB_3.FLDMAP as FLDMAP3, CASE WHEN GENHTAB_3.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF3,
TOC.FLDID4, TOC.FLDTAG4, TOC.FLDTAGA4, GENHTAB_4.FLDTAB AS FLDTAB4, GENHTAB_4.FLDCOM AS FLDCOM4, GENHTAB_4.FLDCOMA AS FLDCOMA4, GENHTAB_4.FLDDFORMAT AS FLDDFORMAT4, GENHTAB_4.FLDIFORMAT AS FLDIFORMAT4, GENHTAB_4.FLDTYPE AS FLDTYPE4, GENHTAB_4.SUBLINKF AS SUBLINKF4,  GENHTAB_4.FLDSEARCH AS FLDSEARCH4, GENHTAB_4.FLDCRITERIA AS FLDCRITERIA4, GENHTAB_4.FLDCHGINF as FLDCHGINF4, GENHTAB_4.FLDLOWER as FLDLOWER4, GENHTAB_4.FLDUPPER as FLDUPPER4, GENHTAB_4.FLDREGEX as FLDREGEX4, GENHTAB_4.FLDFUNC as FLDFUNC4, GENHTAB_4.FLDMAP as FLDMAP4, CASE WHEN GENHTAB_4.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF4,
TOC.FLDID5, TOC.FLDTAG5, TOC.FLDTAGA5, GENHTAB_5.FLDTAB AS FLDTAB5, GENHTAB_5.FLDCOM AS FLDCOM5, GENHTAB_5.FLDCOMA AS FLDCOMA5, GENHTAB_5.FLDDFORMAT AS FLDDFORMAT5, GENHTAB_5.FLDIFORMAT AS FLDIFORMAT5, GENHTAB_5.FLDTYPE AS FLDTYPE5, GENHTAB_5.SUBLINKF AS SUBLINKF5,  GENHTAB_5.FLDSEARCH AS FLDSEARCH5, GENHTAB_5.FLDCRITERIA AS FLDCRITERIA5, GENHTAB_5.FLDCHGINF as FLDCHGINF5, GENHTAB_5.FLDLOWER as FLDLOWER5, GENHTAB_5.FLDUPPER as FLDUPPER5, GENHTAB_5.FLDREGEX as FLDREGEX5, GENHTAB_5.FLDFUNC as FLDFUNC5, GENHTAB_5.FLDMAP as FLDMAP5, CASE WHEN GENHTAB_5.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF5,
TOC.FLDID6, TOC.FLDTAG6, TOC.FLDTAGA6, GENHTAB_6.FLDTAB AS FLDTAB6, GENHTAB_6.FLDCOM AS FLDCOM6, GENHTAB_6.FLDCOMA AS FLDCOMA6, GENHTAB_6.FLDDFORMAT AS FLDDFORMAT6, GENHTAB_6.FLDIFORMAT AS FLDIFORMAT6, GENHTAB_6.FLDTYPE AS FLDTYPE6, GENHTAB_6.SUBLINKF AS SUBLINKF6,  GENHTAB_6.FLDSEARCH AS FLDSEARCH6, GENHTAB_6.FLDCRITERIA AS FLDCRITERIA6, GENHTAB_6.FLDCHGINF as FLDCHGINF6, GENHTAB_6.FLDLOWER as FLDLOWER6, GENHTAB_6.FLDUPPER as FLDUPPER6, GENHTAB_6.FLDREGEX as FLDREGEX6, GENHTAB_6.FLDFUNC as FLDFUNC6, GENHTAB_6.FLDMAP as FLDMAP6, CASE WHEN GENHTAB_6.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF6,
TOC.FLDID7, TOC.FLDTAG7, TOC.FLDTAGA7, GENHTAB_7.FLDTAB AS FLDTAB7, GENHTAB_7.FLDCOM AS FLDCOM7, GENHTAB_7.FLDCOMA AS FLDCOMA7, GENHTAB_7.FLDDFORMAT AS FLDDFORMAT7, GENHTAB_7.FLDIFORMAT AS FLDIFORMAT7, GENHTAB_7.FLDTYPE AS FLDTYPE7, GENHTAB_7.SUBLINKF AS SUBLINKF7,  GENHTAB_7.FLDSEARCH AS FLDSEARCH7, GENHTAB_7.FLDCRITERIA AS FLDCRITERIA7, GENHTAB_7.FLDCHGINF as FLDCHGINF7, GENHTAB_7.FLDLOWER as FLDLOWER7, GENHTAB_7.FLDUPPER as FLDUPPER7, GENHTAB_7.FLDREGEX as FLDREGEX7, GENHTAB_7.FLDFUNC as FLDFUNC7, GENHTAB_7.FLDMAP as FLDMAP7, CASE WHEN GENHTAB_7.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF7,
TOC.FLDID8, TOC.FLDTAG8, TOC.FLDTAGA8, GENHTAB_8.FLDTAB AS FLDTAB8, GENHTAB_8.FLDCOM AS FLDCOM8, GENHTAB_8.FLDCOMA AS FLDCOMA8, GENHTAB_8.FLDDFORMAT AS FLDDFORMAT8, GENHTAB_8.FLDIFORMAT AS FLDIFORMAT8, GENHTAB_8.FLDTYPE AS FLDTYPE8, GENHTAB_8.SUBLINKF AS SUBLINKF8,  GENHTAB_8.FLDSEARCH AS FLDSEARCH8, GENHTAB_8.FLDCRITERIA AS FLDCRITERIA8, GENHTAB_8.FLDCHGINF as FLDCHGINF8, GENHTAB_8.FLDLOWER as FLDLOWER8, GENHTAB_8.FLDUPPER as FLDUPPER8, GENHTAB_8.FLDREGEX as FLDREGEX8, GENHTAB_8.FLDFUNC as FLDFUNC8, GENHTAB_8.FLDMAP as FLDMAP8, CASE WHEN GENHTAB_8.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF8,
TOC.FLDID9, TOC.FLDTAG9, TOC.FLDTAGA9, GENHTAB_9.FLDTAB AS FLDTAB9, GENHTAB_9.FLDCOM AS FLDCOM9, GENHTAB_9.FLDCOMA AS FLDCOMA9, GENHTAB_9.FLDDFORMAT AS FLDDFORMAT9, GENHTAB_9.FLDIFORMAT AS FLDIFORMAT9, GENHTAB_9.FLDTYPE AS FLDTYPE9, GENHTAB_9.SUBLINKF AS SUBLINKF9,  GENHTAB_9.FLDSEARCH AS FLDSEARCH9, GENHTAB_9.FLDCRITERIA AS FLDCRITERIA9, GENHTAB_9.FLDCHGINF as FLDCHGINF9, GENHTAB_9.FLDLOWER as FLDLOWER9, GENHTAB_9.FLDUPPER as FLDUPPER9, GENHTAB_9.FLDREGEX as FLDREGEX9, GENHTAB_9.FLDFUNC as FLDFUNC9, GENHTAB_9.FLDMAP as FLDMAP9, CASE WHEN GENHTAB_9.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF9,
TOC.FLDID10, TOC.FLDTAG10, TOC.FLDTAGA10, GENHTAB_10.FLDTAB AS FLDTAB10, GENHTAB_10.FLDCOM AS FLDCOM10, GENHTAB_10.FLDCOMA AS FLDCOMA10, GENHTAB_10.FLDDFORMAT AS FLDDFORMAT10, GENHTAB_10.FLDIFORMAT AS FLDIFORMAT10, GENHTAB_10.FLDTYPE AS FLDTYPE10, GENHTAB_10.SUBLINKF AS SUBLINKF10,  GENHTAB_10.FLDSEARCH AS FLDSEARCH10, GENHTAB_10.FLDCRITERIA AS FLDCRITERIA10, GENHTAB_10.FLDCHGINF as FLDCHGINF10, GENHTAB_10.FLDLOWER as FLDLOWER10, GENHTAB_10.FLDUPPER as FLDUPPER10, GENHTAB_10.FLDREGEX as FLDREGEX10, GENHTAB_10.FLDFUNC as FLDFUNC10, GENHTAB_10.FLDMAP as FLDMAP10, CASE WHEN GENHTAB_10.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF10,
TOC.FLDID11, TOC.FLDTAG11, TOC.FLDTAGA11, GENHTAB_11.FLDTAB AS FLDTAB11, GENHTAB_11.FLDCOM AS FLDCOM11, GENHTAB_11.FLDCOMA AS FLDCOMA11, GENHTAB_11.FLDDFORMAT AS FLDDFORMAT11, GENHTAB_11.FLDIFORMAT AS FLDIFORMAT11, GENHTAB_11.FLDTYPE AS FLDTYPE11, GENHTAB_11.SUBLINKF AS SUBLINKF11,  GENHTAB_11.FLDSEARCH AS FLDSEARCH11, GENHTAB_11.FLDCRITERIA AS FLDCRITERIA11, GENHTAB_11.FLDCHGINF as FLDCHGINF11, GENHTAB_11.FLDLOWER as FLDLOWER11, GENHTAB_11.FLDUPPER as FLDUPPER11, GENHTAB_11.FLDREGEX as FLDREGEX11, GENHTAB_11.FLDFUNC as FLDFUNC11, GENHTAB_11.FLDMAP as FLDMAP11, CASE WHEN GENHTAB_11.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF11,
TOC.FLDID12, TOC.FLDTAG12, TOC.FLDTAGA12, GENHTAB_12.FLDTAB AS FLDTAB12, GENHTAB_12.FLDCOM AS FLDCOM12, GENHTAB_12.FLDCOMA AS FLDCOMA12, GENHTAB_12.FLDDFORMAT AS FLDDFORMAT12, GENHTAB_12.FLDIFORMAT AS FLDIFORMAT12, GENHTAB_12.FLDTYPE AS FLDTYPE12, GENHTAB_12.SUBLINKF AS SUBLINKF12,  GENHTAB_12.FLDSEARCH AS FLDSEARCH12, GENHTAB_12.FLDCRITERIA AS FLDCRITERIA12, GENHTAB_12.FLDCHGINF as FLDCHGINF12, GENHTAB_12.FLDLOWER as FLDLOWER12, GENHTAB_12.FLDUPPER as FLDUPPER12, GENHTAB_12.FLDREGEX as FLDREGEX12, GENHTAB_12.FLDFUNC as FLDFUNC12, GENHTAB_12.FLDMAP as FLDMAP12, CASE WHEN GENHTAB_12.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF12,
TOC.FLDID13, TOC.FLDTAG13, TOC.FLDTAGA13, GENHTAB_13.FLDTAB AS FLDTAB13, GENHTAB_13.FLDCOM AS FLDCOM13, GENHTAB_13.FLDCOMA AS FLDCOMA13, GENHTAB_13.FLDDFORMAT AS FLDDFORMAT13, GENHTAB_13.FLDIFORMAT AS FLDIFORMAT13, GENHTAB_13.FLDTYPE AS FLDTYPE13, GENHTAB_13.SUBLINKF AS SUBLINKF13,  GENHTAB_13.FLDSEARCH AS FLDSEARCH13, GENHTAB_13.FLDCRITERIA AS FLDCRITERIA13, GENHTAB_13.FLDCHGINF as FLDCHGINF13, GENHTAB_13.FLDLOWER as FLDLOWER13, GENHTAB_13.FLDUPPER as FLDUPPER13, GENHTAB_13.FLDREGEX as FLDREGEX13, GENHTAB_13.FLDFUNC as FLDFUNC13, GENHTAB_13.FLDMAP as FLDMAP13, CASE WHEN GENHTAB_13.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF13,
TOC.FLDID14, TOC.FLDTAG14, TOC.FLDTAGA14, GENHTAB_14.FLDTAB AS FLDTAB14, GENHTAB_14.FLDCOM AS FLDCOM14, GENHTAB_14.FLDCOMA AS FLDCOMA14, GENHTAB_14.FLDDFORMAT AS FLDDFORMAT14, GENHTAB_14.FLDIFORMAT AS FLDIFORMAT14, GENHTAB_14.FLDTYPE AS FLDTYPE14, GENHTAB_14.SUBLINKF AS SUBLINKF14,  GENHTAB_14.FLDSEARCH AS FLDSEARCH14, GENHTAB_14.FLDCRITERIA AS FLDCRITERIA14, GENHTAB_14.FLDCHGINF as FLDCHGINF14, GENHTAB_14.FLDLOWER as FLDLOWER14, GENHTAB_14.FLDUPPER as FLDUPPER14, GENHTAB_14.FLDREGEX as FLDREGEX14, GENHTAB_14.FLDFUNC as FLDFUNC14, GENHTAB_14.FLDMAP as FLDMAP14, CASE WHEN GENHTAB_14.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF14,
TOC.FLDID15, TOC.FLDTAG15, TOC.FLDTAGA15, GENHTAB_15.FLDTAB AS FLDTAB15, GENHTAB_15.FLDCOM AS FLDCOM15, GENHTAB_15.FLDCOMA AS FLDCOMA15, GENHTAB_15.FLDDFORMAT AS FLDDFORMAT15, GENHTAB_15.FLDIFORMAT AS FLDIFORMAT15, GENHTAB_15.FLDTYPE AS FLDTYPE15, GENHTAB_15.SUBLINKF AS SUBLINKF15,  GENHTAB_15.FLDSEARCH AS FLDSEARCH15, GENHTAB_15.FLDCRITERIA AS FLDCRITERIA15, GENHTAB_15.FLDCHGINF as FLDCHGINF15, GENHTAB_15.FLDLOWER as FLDLOWER15, GENHTAB_15.FLDUPPER as FLDUPPER15, GENHTAB_15.FLDREGEX as FLDREGEX15, GENHTAB_15.FLDFUNC as FLDFUNC15, GENHTAB_15.FLDMAP as FLDMAP15, CASE WHEN GENHTAB_15.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF15
FROM       
TOC       
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID1, @P_SEGMENT)) AS GENHTAB_1
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID2, @P_SEGMENT)) AS GENHTAB_2
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID3, @P_SEGMENT)) AS GENHTAB_3
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID4, @P_SEGMENT)) AS GENHTAB_4
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID5, @P_SEGMENT)) AS GENHTAB_5
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID6, @P_SEGMENT)) AS GENHTAB_6
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID7, @P_SEGMENT)) AS GENHTAB_7
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID8, @P_SEGMENT)) AS GENHTAB_8
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID9, @P_SEGMENT)) AS GENHTAB_9
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID10, @P_SEGMENT)) AS GENHTAB_10
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID11, @P_SEGMENT)) AS GENHTAB_11
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID12, @P_SEGMENT)) AS GENHTAB_12
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID13, @P_SEGMENT)) AS GENHTAB_13
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID14, @P_SEGMENT)) AS GENHTAB_14
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID15, @P_SEGMENT)) AS GENHTAB_15
WHERE  TOC.TOC = @P_TOC 


GO

